extra_head_css:
.screenshot-workspace { display: flex; gap: 24px; flex-wrap: wrap; }
    .screenshot-sidebar { flex: 0 0 300px; display: flex; flex-direction: column; gap: 14px; }
    .screenshot-canvas-area { flex: 1; min-width: 300px; }

    .control-group { display: flex; flex-direction: column; gap: 6px; }
    .control-group label { font-size: .8rem; color: var(--text-secondary); font-weight: 500; }
    .control-group select, .control-group input[type="number"] {
      padding: 8px 10px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .85rem;
    }
    .control-group input[type="range"] { width: 100%; }
    .control-group input[type="color"] {
      width: 100%; height: 36px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); cursor: pointer; padding: 2px;
    }

    .gradient-presets { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }
    .gradient-swatch {
      width: 100%; aspect-ratio: 1; border-radius: 8px; cursor: pointer;
      border: 2px solid transparent; transition: all .2s; position: relative;
    }
    .gradient-swatch:hover { transform: scale(1.1); }
    .gradient-swatch.active { border-color: var(--accent); box-shadow: 0 0 0 2px rgba(99,102,241,.3); }

    .frame-btns { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; }
    .frame-btn {
      padding: 8px; border: 1px solid var(--border); border-radius: 8px;
      background: var(--bg-primary); color: var(--text-secondary); cursor: pointer;
      text-align: center; font-size: .8rem; transition: all .2s;
    }
    .frame-btn:hover { border-color: var(--accent); color: var(--text-primary); }
    .frame-btn.active { border-color: var(--accent); background: rgba(99,102,241,.1); color: var(--accent); }

    .canvas-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border: 1px solid var(--border); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 300px;
      overflow: auto;
    }
    .canvas-wrapper canvas { max-width: 100%; max-height: 600px; border-radius: 4px; }

    .info-row {
      display: flex; gap: 12px; font-size: .8rem; color: var(--text-secondary);
      padding: 8px 12px; background: var(--bg-secondary); border-radius: 8px;
    }
    .info-row span { display: flex; align-items: center; gap: 4px; }

    @media (max-width: 768px) {
      .screenshot-workspace { flex-direction: column; }
      .screenshot-sidebar { flex: none; width: 100%; }
    }
